const screens = ['/ops/radar', '/ops/operations', '/ops/launchpad', '/ops/rules'];
for (const path of screens) {
  await page.goto(path);
  const label = page.getByRole('status', { name: 'Admin' });
  if (await label.count()) {
    await expect(label.first()).toHaveCSS('font-size', '10px');
    break;
  }
}
